#!/usr/bin/env python3
"""Record newly listed resources between two trusted main-branch revisions."""

import argparse
from datetime import datetime, timezone
from pathlib import Path
import re
import subprocess

ROOT = Path(__file__).resolve().parent.parent
ENTRY = re.compile(r"^- \[([^\]]+)\]\((https?://[^\s)]+)\)(.*)$")
LINK = re.compile(r"\[[^\]]+\]\((https?://[^\s)]+)\)")
HEADER = """# Recently Added

New resources accepted into [Awesome Codex CLI](README.md), recorded automatically from changes on main.

<!-- Generated by scripts/update-recently-added.py. Newest entries first. -->

"""


def resources(text):
    entries = {}
    category = "Resources"
    for line in text.splitlines():
        if line.startswith("## ") or line.startswith("### "):
            category = line.lstrip("# ")
        match = ENTRY.match(line)
        if match:
            name, url, tail = match.groups()
            if tail.startswith(" - ") or tail.startswith(" by "):
                entries.setdefault(url.rstrip("/").lower(), (name, url, tail, category))
    return entries


def additions(before, after, recorded):
    # Compare all existing links, so moving a link into a list isn't a new resource.
    known = {url.rstrip("/").lower() for url in LINK.findall(before + "\n" + recorded)}
    return [entry for key, entry in resources(after).items() if key not in known]


def revision_text(revision):
    return subprocess.check_output(
        ["git", "show", f"{revision}:README.md"], cwd=ROOT, text=True
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--before", required=True)
    parser.add_argument("--after", required=True)
    args = parser.parse_args()
    if set(args.before) == {"0"}:
        print("Skipping initial branch creation; no baseline available")
        return
    path = ROOT / "RECENTLY_ADDED.md"
    recorded = path.read_text() if path.exists() else ""
    new = additions(revision_text(args.before), revision_text(args.after), recorded)
    if not new:
        print("No new resources")
        return
    date = datetime.fromtimestamp(int(subprocess.check_output(
        ["git", "show", "-s", "--format=%ct", args.after], cwd=ROOT, text=True
    )), timezone.utc).date().isoformat()
    entries = []
    for name, url, tail, category in new:
        anchor = re.sub(r"[^\w\s-]", "", category.lower()).strip().replace(" ", "-")
        entries.append(f"- {date} — [{name}]({url}){tail} ([{category}](README.md#{anchor}))")
    old_entries = [line for line in recorded.splitlines() if line.startswith("- ")]
    path.write_text(HEADER + "\n".join(entries + old_entries) + "\n")
    print(f"Recorded {len(new)} new resources")


if __name__ == "__main__":
    main()
